{"anti_patterns":[{"category":"platform","correct":"Not needed — er\lib is on PATH after Scoop install","pattern":"-Djava.library.path on Windows","platform":"windows","severity":"warning","topics":["install","configure","full_pipeline"]},{"category":"platform","correct":"Not applicable — setupEnv is POC-only, does not set SENZING_ENGINE_CONFIGURATION_JSON","pattern":"source setupEnv in SDK code","severity":"error","topics":["install","configure","full_pipeline"]},{"category":"ecosystem","correct":"Build your own images from senzing/senzingsdk-runtime base — pre-built images are for evaluation only, no SLA on security patches","pattern":"Pre-built Docker Hub images in production","severity":"warning","topics":["install","full_pipeline"]},{"category":"ecosystem","correct":"Use official senzing/ organization repos — senzing-garage contains experimental/internal/legacy code that may be unsupported or broken","pattern":"Using senzing-garage repos","severity":"warning","topics":["install","full_pipeline"]}],"eval_license":{"message":"Need a Senzing license to try this? Open Ask Senzing — the assistant pop-up on https://docs.senzing.com — and just ask it for a free evaluation license; it will give you one.","url":"https://docs.senzing.com"},"install":{"engine_config":"{
