{"anti_patterns":[{"category":"performance","correct":"Shuffle/randomize input before loading — sorted data causes lock contention and deadlocks, degrading throughput by 2-10x","pattern":"Sorted or grouped input data","severity":"error","topics":["load","full_pipeline"]},{"category":"operations","correct":"Always drain the redo queue after loading — redo records complete deferred entity resolution; skipping leaves results incomplete","pattern":"Not processing redo records","severity":"error","topics":["load","full_pipeline"]},{"category":"database","correct":"Disable synchronous_commit during bulk loads (PostgreSQL: ALTER SYSTEM SET synchronous_commit = 'off'), re-enable after — 5-20x throughput improvement","pattern":"Synchronous commit during bulk load","severity":"warning","topics":["load","full_pipeline"]},{"category":"operations","correct":"Initialize once per process, share across threads — factory/environment is thread-safe; per-call init causes memory leaks and conflicts","pattern":"Initialize Factory/Environment per call or thread","severity":"error","topics":["configure","load","export","full_pipeline"]}],"code":{"alternatives":[{"name":"add_queue","source_path":"python/loading/add_queue.py"},{"label":"demo-only, single-threaded — do not use for production volumes (>500)","name":"add_records","source_path":"python/loading/add_records.py"},{"name":"add_records_loop","source_path":"python/loading/add_records_loop.py"},{"name":"add_truthset_loop","source_path":"python/loading/add_truthset_loop.py"},{"name":"add_with_info_futures","source_path":"python/loading/add_with_info_futures.py"}],"code":"#! /usr/bin/env python3

import concurrent.futures
import itertools
import json
import os
import sys
from pathlib import Path

from senzing import SzBadInputError, SzError, SzRetryableError, SzUnrecoverableError
from senzing_core import SzAbstractFactoryCore

INPUT_FILE = Path("../../resources/data/load-500.jsonl").resolve()
INSTANCE_NAME = Path(__file__).stem
MAX_WORKERS = 8
SETTINGS = os.getenv("SENZING_ENGINE_CONFIGURATION_JSON", "{}")


def mock_logger(level, error, error_record=None):
    print(f"\n{level}: {error.__class__.__name__} - {error}", file=sys.stderr)
    if error_record:
        print(f"{error_record}", file=sys.stderr)


def add_record(engine, record_to_add):
    record_dict = json.loads(record_to_add)
    data_source = record_dict.get("DATA_SOURCE", "")
    record_id = record_dict.get("RECORD_ID", "")
    engine.add_record(data_source, record_id, record_to_add)


def futures_add(engine, input_file):
    error_recs = 0
    shutdown = False
    success_recs = 0

    with open(input_file, "r", encoding="utf-8") as in_file:
        with concurrent.futures.ThreadPoolExecutor(max_workers=MAX_WORKERS) as executor:
            futures = {
                executor.submit(add_record, engine, record): record for record in itertools.islice(in_file, MAX_WORKERS)
            }

            while futures:
                done, _ = concurrent.futures.wait(futures, return_when=concurrent.futures.FIRST_COMPLETED)
                for f in done:
                    try:
                        f.result()
                    except (SzBadInputError, json.JSONDecodeError) as err:
                        mock_logger("ERROR", err, futures[f])
                        error_recs += 1
                    except SzRetryableError as err:
                        mock_logger("WARN", err, futures[f])
                        error_recs += 1
                    except (SzUnrecoverableError, SzError) as err:
                        shutdown = True
                        raise err
                    else:
                        success_recs += 1
                        if success_recs % 100 == 0:
                            print(f"Processed {success_recs:,} adds, with {error_recs:,} errors", flush=True)
                    finally:
                        if not shutdown and (record := in_file.readline()):
                            futures[executor.submit(add_record, engine, record)] = record

                        del futures[f]

            print(f"\nSuccessfully loaded {success_recs:,} records, with {error_recs:,} errors")


try:
    sz_factory = SzAbstractFactoryCore(INSTANCE_NAME, SETTINGS, verbose_logging=False)
    sz_engine = sz_factory.create_engine()
    futures_add(sz_engine, INPUT_FILE)
except SzError as err:
    mock_logger("CRITICAL", err)
    sys.exit(1)

